class Solution {
    public:int countPaths(vector<vector<int>>& grid){
        const long long mod=1000000007;
        int rows=grid.size(),columns=grid[0].size(),total=rows*columns;
        vector<int> order(total);
        iota(order.begin(),order.end(),0);
        sort(order.begin(),order.end(),[&](int a,int b){
            return grid[a/columns][a%columns]<grid[b/columns][b%columns];
        });
        vector<long long> dp(total,1);
        int directions[5]={
            1,0,-1,0,1
        };
        long long answer=0;
        for(int index:order){
            int row=index/columns,column=index%columns;
            for(int d=0;d<4;++d){
                int r=row+directions[d],c=column+directions[d+1];
                if(r>=0&&r<rows&&c>=0&&c<columns&&grid[r][c]<grid[row][column])dp[index]=(dp[index]+dp[r*columns+c])%mod;
            }
            answer=(answer+dp[index])%mod;
        }
        return answer;
    }
};
